n, L = map(int, input().split())
inf = 10**10
dp = [inf for i in range(L)]
dp[0] = 0
ans = inf
for i in range(n):
    c, l = map(int, input().split())
    for j in range(max(L - l, 0), L):
        ans = min(ans, dp[j] + c)
    for j in range(L - 1, l - 1, -1):
        dp[j] = min(dp[j], dp[j - l] + c)

if ans == inf:
    print("no solution")
else:
    print(ans)
